void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Texture size
    vec2 iResolution = iResolution.xy;
    float width = iResolution.x;
    float height = iResolution.y;

    // Parameters
    float EdgeRadius = 2.0; // 1.0 to 16.0
    float BlurRadius = 8.0; // 1.0 to 16.0
    float BoundrySharpenVsBlur = 0.03; // 0.01 .. 0.2
    float SharpenStrength = 0.11; // 0.0 .. 4.0

    // Calculate normalized texture coordinates
    vec2 tex = fragCoord.xy / iResolution.xy;

    // Sample the texture at the given coordinates
    vec4 c0 = texture(iChannel0, tex);

    // Convert to YUV
    vec3 rgb = c0.rgb;


    float y = 0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b;
    float u = -0.169 * rgb.r - 0.331 * rgb.g + 0.499 * rgb.b;
    float v = 0.499 * rgb.r - 0.460 * rgb.g - 0.040 * rgb.b;

    // Initialize min/max values for Y channel
    float minY = y;
    float maxY = y;

    // Sampling step sizes
    float dx = 1.0 / width;
    float dy = 1.0 / height;


    // Loop through the neighboring pixels within the radius
    for (int y1 = -int(EdgeRadius); y1 <= int(EdgeRadius); y1++) {
        for (int x1 = -int(EdgeRadius); x1 <= int(EdgeRadius); x1++) {
            if (float(x1 * x1 + y1 * y1) <= EdgeRadius * EdgeRadius) {
                vec2 offset = vec2(float(x1) * dx, float(y1) * dy);
                vec4 neighborColor = texture(iChannel0, tex + offset);

                // Convert the neighboring color to YUV and get the Y component
                rgb = neighborColor.rgb;
                float neighborY = 0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b;                         
                // Update min and max Y values
                minY = min(minY, neighborY);
                maxY = max(maxY, neighborY);
            }
        }
    }

    float avg = 0.0;
    float cnt = 0.0;
        for (int y1 = -int(BlurRadius); y1 <= int(BlurRadius); y1++) {
        for (int x1 = -int(BlurRadius); x1 <= int(BlurRadius); x1++) {
            if (float(x1 * x1 + y1 * y1) <= BlurRadius * BlurRadius) {
                vec2 offset = vec2(float(x1) * dx, float(y1) * dy);
                vec4 neighborColor = texture(iChannel0, tex + offset);

                // Convert the neighboring color to YUV and get the Y component
                rgb = neighborColor.rgb;
                float neighborY = 0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b;                
                avg = avg + neighborY;
                cnt = cnt + 1.0;           
            }
        }
    }

    avg=avg/cnt;
    float edge=(abs(maxY - avg)+abs(minY - avg));

    // Sharpen or blur 
    if (edge > BoundrySharpenVsBlur){
     // Sharpen
      if (abs(maxY - y) < abs(minY - y)) {
          y = maxY+edge*SharpenStrength;
      } else {
          y = minY-edge*SharpenStrength;
      }
    }
    else
    {
      // Blur
      y = avg;
    }

    // Convert YUV back to RGB
    float r= y + 1.402 * v;
    float g = y - 0.344136 * u - 0.714136 * v;
    float b = y + 1.772 * u; 


        // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float szSlide = .001;        
    vec2 mouse =iMouse.xy/ iResolution.xy;
    if(mouse.x <= 0.0 &&  mouse.y <= 0.0) mouse.x = .5; // to show initial screen half splitted

	fragColor = uv.x<mouse.x-szSlide  ? texture(iChannel0,uv)
          : (uv.x>mouse.x+szSlide ?  vec4(r, g, b, 1.0) 
          :  vec4(1.0));        
}
